-- Versioned default templates and their immutable term snapshots.
CREATE TABLE "RubricTemplate" (
  "id" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "RubricTemplate_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "RubricTemplateVersion" (
  "id" TEXT NOT NULL,
  "templateId" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  "status" "RubricVersionStatus" NOT NULL DEFAULT 'DRAFT',
  "definition" JSONB NOT NULL,
  "sourceDescription" TEXT,
  "changeNote" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "publishedAt" TIMESTAMP(3),
  CONSTRAINT "RubricTemplateVersion_pkey" PRIMARY KEY ("id")
);
ALTER TABLE "RubricVersion" ADD COLUMN "sourceTemplateVersionId" TEXT, ADD COLUMN "sourceTermCode" TEXT, ADD COLUMN "changeNote" TEXT;
CREATE UNIQUE INDEX "RubricTemplate_code_key" ON "RubricTemplate"("code");
CREATE UNIQUE INDEX "RubricTemplateVersion_templateId_version_key" ON "RubricTemplateVersion"("templateId", "version");
CREATE INDEX "RubricTemplateVersion_templateId_status_idx" ON "RubricTemplateVersion"("templateId", "status");
CREATE INDEX "RubricVersion_sourceTemplateVersionId_idx" ON "RubricVersion"("sourceTemplateVersionId");
ALTER TABLE "RubricTemplateVersion" ADD CONSTRAINT "RubricTemplateVersion_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "RubricTemplate"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RubricVersion" ADD CONSTRAINT "RubricVersion_sourceTemplateVersionId_fkey" FOREIGN KEY ("sourceTemplateVersionId") REFERENCES "RubricTemplateVersion"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- The initial standard is the approved rubric configuration, not student score data.
INSERT INTO "RubricTemplate" ("id", "code", "name") VALUES ('dut-rubric-default', 'DUT_DEFAULT', 'Bộ tiêu chí ĐHBK Đà Nẵng');
INSERT INTO "RubricTemplateVersion" ("id", "templateId", "version", "status", "definition", "sourceDescription", "publishedAt")
VALUES ('dut-rubric-default-v1', 'dut-rubric-default', 1, 'PUBLISHED', $json${"categories":[{"code":"KHUNG_I","name":"Ý thức tham gia học tập","maxScore":20,"position":1,"criteria":[{"code":"1","name":"Đi học đầy đủ, đúng giờ, nghiêm túc trong giờ học","description":"Không được thi cuối kỳ do vắng quá thời gian quy định: trừ 3 điểm/học phần. Bị nhắc nhở hoặc không được vào lớp, không nghiêm túc trong giờ học: trừ 1 điểm/lần.","maxScore":6,"scoringConfig":{"kind":"attendance_penalty","requiredData":["examBans","classWarnings"],"baseScore":6,"examBanPenalty":3,"warningPenalty":1}},{"code":"2","name":"Có ý thức, trách nhiệm khi tham gia nhóm làm việc chung","description":"Vắng làm việc nhóm không lý do: trừ 2 điểm/lần; có lý do từ lần thứ 2: trừ 1 điểm/lần. Không hoàn thành nội dung được phân công đúng hạn: trừ hết điểm.","maxScore":3,"scoringConfig":{"kind":"group_penalty","requiredData":["unexcusedAbsences","excusedAbsences","missedGroupDeadlines"],"unexcusedPenalty":2,"excusedPenaltyFromSecond":1}},{"code":"3","name":"Có tinh thần cố gắng, phấn đấu trong học tập","description":"Điểm trung bình học kỳ từ loại trung bình: 3 điểm; từ trung bình trở lên và cao hơn học kỳ trước: 4 điểm; từ loại giỏi trở lên và cao hơn học kỳ trước: 5 điểm. Học lực yếu trở xuống và thuộc diện cảnh báo học tập: trừ hết điểm.","maxScore":5,"scoringConfig":{"kind":"academic_effort","requiredData":["academicTier","improvedFromPreviousTerm","academicWarning"]}},{"code":"4","name":"Tham gia câu lạc bộ học thuật, nhóm nghiên cứu hoặc khởi nghiệp đổi mới sáng tạo","description":"Tham gia đơn vị do Trường/Khoa/Đoàn Thanh niên/Hội Sinh viên quản lý; cần quyết định thành lập hoặc xác nhận hợp lệ.","maxScore":3,"scoringConfig":{"kind":"verified_boolean","requiredData":["eligibleMembership"],"passScore":3}},{"code":"5","name":"Tham gia và đạt thành tích trong nghiên cứu khoa học hoặc Olympic môn học","description":"Tham gia nhưng không đạt giải: 2 điểm; đạt từ giải khuyến khích trở lên: 3 điểm; cần xác nhận của đơn vị có thẩm quyền.","maxScore":3,"scoringConfig":{"kind":"award_tier","requiredData":["awardTier"],"scores":{"PARTICIPATED":2,"CONSOLATION_OR_HIGHER":3}}}]},{"code":"KHUNG_II","name":"Ý thức chấp hành nội quy, quy chế","maxScore":25,"position":2,"criteria":[{"code":"6","name":"Chấp hành chủ trương, định hướng và phong trào của Nhà trường","description":"Thực hiện các chủ trương, định hướng, phong trào do Bộ Giáo dục và Đào tạo, Đại học Đà Nẵng, Nhà trường và cơ quan có thẩm quyền triển khai.","maxScore":5,"scoringConfig":{"kind":"manual_verified","requiredData":["officialAssessment"]}},{"code":"7","name":"Không vi phạm quy chế, quy định, nội quy của Trường, Khoa, Lớp","description":"Không đóng học phí đúng hạn dẫn đến khóa tài khoản, không tham gia tuần sinh hoạt công dân, vi phạm điều cấm hoặc không tham gia khảo sát: 0 điểm theo quy chế. Khóa tài khoản do nguyên nhân khác: trừ 5 điểm/lần. Không hoàn thành việc lớp giao: trừ 3 điểm/lần, từ 3 lần: 0 điểm. Vắng họp lớp không lý do: trừ 10 điểm/lần; có lý do: trừ 3 điểm/lần.","maxScore":15,"scoringConfig":{"kind":"conduct_penalty","requiredData":["tuitionCompliance","studentWeekParticipation","disciplinaryViolation","nonCauseAccountLocks","classTaskFailures","unexcusedClassMeetingAbsences","excusedClassMeetingAbsences","requiredSurveyParticipation"],"baseScore":15}},{"code":"8","name":"Tham gia hoạt động giáo dục chính trị, tư tưởng, kỹ năng mềm và hướng dẫn nội quy","description":"Tham gia tối thiểu 1 hoạt động trong học kỳ: 5 điểm; không tham gia: 0 điểm.","maxScore":5,"scoringConfig":{"kind":"activity_threshold","requiredData":["verifiedActivityCount"],"tiers":[{"min":1,"score":5}]}}]},{"code":"KHUNG_III","name":"Ý thức tham gia hoạt động chính trị, xã hội, phong trào","maxScore":20,"position":3,"criteria":[{"code":"9","name":"Tham gia hoạt động văn hóa, văn nghệ, thể thao","description":"Tham gia 1 lần: 5 điểm; 2 lần: 7 điểm; từ 3 lần: 10 điểm; không tham gia: 0 điểm. Vai trò cổ vũ được tính 50% mức tương ứng.","maxScore":10,"scoringConfig":{"kind":"activity_threshold","requiredData":["verifiedActivityCount"],"cheerleaderMultiplier":0.5,"tiers":[{"min":1,"score":5},{"min":2,"score":7},{"min":3,"score":10}]}},{"code":"10","name":"Tham gia hoạt động tuyên truyền, giáo dục chính trị, phòng chống tội phạm và tệ nạn xã hội","description":"Hoạt động do Trường, Khoa hoặc tổ chức Đoàn/Hội tổ chức: tham gia 1 lần 5 điểm; 2 lần 7 điểm; từ 3 lần 10 điểm; không tham gia 0 điểm.","maxScore":10,"scoringConfig":{"kind":"activity_threshold","requiredData":["verifiedActivityCount"],"tiers":[{"min":1,"score":5},{"min":2,"score":7},{"min":3,"score":10}]}}]},{"code":"KHUNG_IV","name":"Ý thức công dân trong quan hệ cộng đồng","maxScore":25,"position":4,"criteria":[{"code":"11","name":"Có ý thức chấp hành chủ trương, pháp luật tại nơi cư trú và trong cộng đồng","description":"Không tham gia bảo hiểm y tế; không đăng ký tạm trú/tạm vắng hoặc khai báo không chính xác; bị xử lý vi phạm từ mức nhắc nhở trở lên: 0 điểm. Không vi phạm: 10 điểm.","maxScore":10,"scoringConfig":{"kind":"all_conditions","requiredData":["healthInsurance","residenceDeclaration","communityViolations"],"passScore":10,"failScore":0}},{"code":"12","name":"Tham gia hoạt động phục vụ cộng đồng, công ích, tình nguyện và công tác xã hội","description":"Không tham gia: 0 điểm. Từ 1 hoạt động và điểm quy đổi tối thiểu 5 điểm/học kỳ: 5 điểm; từ 2 hoạt động và 10 điểm quy đổi: 7 điểm; từ 3 hoạt động và 15 điểm quy đổi: 10 điểm.","maxScore":10,"scoringConfig":{"kind":"community_activity_tier","requiredData":["verifiedActivityCount","convertedCommunityPoints"],"tiers":[{"minCount":1,"minPoints":5,"score":5},{"minCount":2,"minPoints":10,"score":7},{"minCount":3,"minPoints":15,"score":10}]}},{"code":"13","name":"Tham gia tổ chức hoạt động của lớp, Khoa, Trường hoặc làm cộng tác viên","description":"Tham gia ban tổ chức hoạt động hoặc làm cộng tác viên cho Nhà trường; cần xác nhận hợp lệ của đơn vị tổ chức.","maxScore":5,"scoringConfig":{"kind":"verified_boolean","requiredData":["organizerConfirmation"],"passScore":5}}]},{"code":"KHUNG_V","name":"Ý thức và kết quả khi tham gia công tác cán bộ lớp, đoàn thể","maxScore":10,"position":5,"criteria":[{"code":"14","name":"Hoàn thành tốt nhiệm vụ cán bộ lớp, Đoàn, Hội hoặc câu lạc bộ","description":"Được tập thể bình chọn công nhận (khảo sát đạt trên 90%) và được giảng viên cố vấn/chủ nhiệm hoặc đơn vị phụ trách xác nhận.","maxScore":4,"scoringConfig":{"kind":"leadership_duty","requiredData":["leadershipRole","collectiveApprovalPercent","advisorConfirmation"],"passScore":4}},{"code":"15","name":"Hoàn thành xuất sắc nhiệm vụ và được khen thưởng","description":"Dành cho cán bộ lớp, Đoàn, Hội hoặc câu lạc bộ hoàn thành xuất sắc nhiệm vụ, có quyết định khen thưởng/giấy khen hợp lệ.","maxScore":3,"scoringConfig":{"kind":"verified_boolean","requiredData":["excellentDutyConfirmation","awardEvidence"],"passScore":3}},{"code":"16","name":"Cán bộ đoàn thể được khen thưởng cấp Trường trở lên","description":"Thành viên Ban cán sự lớp, Ban Chấp hành Đoàn/Hội hoặc Ban chủ nhiệm câu lạc bộ được khen thưởng cấp Trường trở lên; cần quyết định khen thưởng/giấy khen.","maxScore":3,"scoringConfig":{"kind":"verified_boolean","requiredData":["leadershipRole","institutionAwardEvidence"],"passScore":3}}]}]}$json$::jsonb, 'Cấu hình tiêu chí theo tài liệu trường cung cấp', CURRENT_TIMESTAMP);
